// Pixel-art UI icons from /ui/icons.png (generated by scripts/generateCustomProps.py)
const NAMES = ['book', 'portrait', 'scroll', 'letter', 'tv', 'pin', 'gear', 'key',
  'sun', 'moon', 'leaf', 'flower', 'snow', 'code', 'briefcase', 'sprout'];

export default function Icon({ name, scale = 2, className = '' }) {
  const i = NAMES.indexOf(name);
  if (i < 0) return null;
  const s = 16 * scale;
  return (
    <span
      className={`icon ${className}`}
      aria-hidden
      style={{
        width: s,
        height: s,
        backgroundImage: 'url(/ui/icons.png)',
        backgroundSize: `${NAMES.length * s}px ${s}px`,
        backgroundPosition: `${-i * s}px 0`,
      }}
    />
  );
}
